# The dialect table: (id, cat, {db: cell}). cell = str (code) | dict(c=code, w=word key, v=version, x=1 not built in)
def W(w, c=None): return {'w': w, **({'c': c} if c else {})}
def X(c=None, w=None): d = {'x': 1}; (c and d.update(c=c)); (w and d.update(w=w)); return d
def V(v, c): return {'v': v, 'c': c}
